FRAGMENTS = {
    "block-section-spells-4-1/item/0": "<<Charm Monster>> ^^(^^[[1|XGtE]]^^)^^: чудовий нелетальний спосіб упоратися з ворогами. Не вимагає, щоб ціль могла вас розуміти, але в іншому має ті самі ускладнення, що й <<Charm Person>>: ціль дружня лише до вас, а коли заклинання закінчується, вона знає, що її причарували.",
    "block-section-spells-4-1/item/1": "<<Compulsion>> ^^(^^[[1|PHB]]^^)^^: технічно ситуативне, але якщо вдасться змусити групу ворогів побігти в один бік і збитися біля стіни чи чогось подібного, по них дуже легко вдарити великою областю дії. На жаль, загнати їх у щось на кшталт <<Wall of Fire|Стіни вогню>> не вийде.",
    "block-section-spells-4-1/item/2": "<<Confusion>> ^^(^^[[1|PHB]]^^)^^: я ненавиджу <<Confusion>> ще з 3-ї редакції. Воно непередбачуване, ненадійне й робить бій удвічі довшим, ніж зазвичай. Чудово, що воно діє по області, і ви, можливо, зможете змусити істот атакувати своїх союзників, але занадто багато точок відмови, щоб покладатися на нього як на надійний варіант.",
    "block-section-spells-4-1/item/3": "<<Dimension Door>> ^^(^^[[1|PHB]]^^)^^: <<Misty Step|Туманного кроку>> у списку заклинань Барда чомусь немає, а можливість телепортуватися з жахливої ситуації (як-от мотузки чи захоплення) надзвичайно корисна.",
    "block-section-spells-4-1/item/4": "<<Freedom of Movement>> ^^(^^[[1|PHB]]^^)^^: гарне, але ситуативне. Якщо вам треба вирватися з пут чи захоплення, накладіть <<Dimension Door>>.",
    "block-section-spells-4-1/item/5": "<<Greater Invisibility>> ^^(^^[[1|PHB]]^^)^^: невидимість у 5e *справді* чудова, а бігати цілу хвилину, будучи майже невловимою ціллю, — величезна перевага.",
    "block-section-spells-4-1/item/6": "<<Hallucinatory Terrain>> ^^(^^[[1|PHB]]^^)^^: ситуативно. Якщо вам не потрібні саме 24-годинна тривалість і величезна область дії, вистачить <<Major Image|Оживленого образу>>.",
    "block-section-spells-4-1/item/7": "<<Locate Creature>> ^^(^^[[1|PHB]]^^)^^: ефективніше за звичайне вистежування, але дальність 1000 футів може стати проблемою, якщо ціль активно тікає від вас. Якщо збираєтеся це використовувати, переконайтеся, що рухаєтеся швидше за ціль.",
    "block-section-spells-4-1/item/8": "<<Phantasmal Killer>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): попри те, як повільно воно вбиває ціль, це чудове одноцільове заклинання, а масштабування рівнем заклинання просто фантастичне. Проти великих кремезних ворогів, які часто мають погані ментальні характеристики, ряткидок буде важко пройти, а стан Наляканий значно знизить ефективність їхніх атак і перевірок характеристик. Як працює стан Наляканий, дещо плутано, бо не вказано, де саме зʼявляється «ілюзорний прояв», якщо він взагалі має розташування. Гадаю, задум у тому, що ціль Налякана, але її рух не обмежується так, як зазвичай обмежує стан Наляканий. Оскільки накладання <<Phantasmal Killer|Фантомного вбивці>> збільшує шкоду на к10 щоразу (а не лише на першому кидку шкоди, як у багатьох заклинань), воно лишається ефективним варіантом далеко за межами свого рівня.",
    "block-section-spells-4-1/item/9": "<<Polymorph>> ^^(^^[[1|PHB]]^^)^^: фантастичне й універсальне, але й дуже складне. Дивіться наш [[2|практичний гайд про «<<c:Polymorph>>»]], щоб отримати детальні поради, як вичавити максимум із <<Polymorph|Перевтілення>>.",
    "block-section-spells-4-1/item/10": "<<Raulothim's Psychic Lance>> ^^(^^[[1|FToD]]^^)^^: ситуативне за задумом. Шкода низька для заклинання такого рівня, особливо одноцільового, але шкода сама по собі — не причина, чому ви тут. Ряткидок — Інтелекту, а це зазвичай одні з найнижчих ряткидків навіть на дуже високих рівнях, і ціль при провалі стає Недієздатною, втрачаючи хід, тож попри те, що воно одноцільове з невиразною шкодою, це потужний інструмент проти поодиноких ворогів. Ще краще те, що якщо ви знаєте імʼя цілі (часто легко для іменованих антагоністів), можна накласти це без прямої видимості, ховаючись за стінами, в областях магічної темряви чи десь іще безпечно.",
    "block-section-spells-5-1/item/0": "<<Animate Objects>> ^^(^^[[1|PHB]]^^)^^: за умови, що для заклинання є достатньо матеріалу, воно може працювати в найрізноманітніших сутичках. Крихітні й Величезні — явно найсмертоносніші варіанти, тож зазвичай ви оживлятимете або одну велику річ, або купу крихітних. Придатні предмети знайти неважко: вистачить навіть випадкового сміття. Проте тривалість коротка, а оживлені предмети тендітні й не стають сильнішими з ростом вашого рівня, тож, можливо, ви захочете перенавчити це заклинання на щось інше, коли кілька рівнів ним натішитеся.",
    "block-section-spells-5-1/item/1": "<<Awaken>> ^^(^^[[1|PHB]]^^)^^: цікаве, але надзвичайно ситуативне.",
    "block-section-spells-5-1/item/2": "<<Dominate Person>> ^^(^^[[1|PHB]]^^)^^: якщо вам не часто трапляються вороги-гуманоїди, воно може не вартувати зусиль. Але якщо трапляються, підкорити ворога й перетворити його на тимчасового союзника — дуже ефективно.",
    "block-section-spells-5-1/item/3": "<<Dream>> ^^(^^[[1|PHB]]^^)^^: хоч саме по собі це заклинання може бути дуже потужним, його можна використати лише поза боєм, і на його застосування багато обмежень. Якби Барду було легше змінювати відомі заклинання, це було б нормально, але кількість відомих заклинань у вас вкрай обмежена, а ви хочете, щоб усі вони були стабільно корисними. Якщо вам справді хочеться це заклинання, переконайтеся, що серед ваших відомих заклинань вистачає інших, які покриють ваші потреби в бою.",
    "block-section-spells-5-1/item/4": "<<Geas>> ^^(^^[[1|PHB]]^^)^^: надто ситуативне, щоб витрачати на нього відоме заклинання. Воно чудове для заклиначів на кшталт Кліриків і Чарівників, але використовується надто рідко, щоб марнувати на його вивчення скромні ресурси в надії, що колись воно стане в пригоді.",
    "block-section-spells-5-1/item/5": "<<Greater Restoration>> ^^(^^[[1|PHB]]^^)^^: якщо у вашій групі немає Клірика, вам воно потрібне.",
    "block-section-spells-5-1/item/6": "<<Hold Monster>> ^^(^^[[1|PHB]]^^)^^: чудовий приклад заклинання «пройди ряткидок або страждай»{{save-or-suck}}. За винятком нежиті, воно діє на будь-який тип істот, а параліч виводить істоту з бою майже так само, як її вбивство. Якщо у вас є союзник, що бʼється в ближньому бою, пошліть його добивати ближніми атаками. Автоматичні критичні влучання надто привабливі, щоб багато союзників ближнього бою їх проминули. Памʼятайте, що цілі роблять новий ряткидок наприкінці кожного свого ходу, тож треба діяти швидко, поки цілі ще під дією.",
    "block-section-spells-5-1/item/7": "<<Legend Lore>> ^^(^^[[1|PHB]]^^)^^: надто ситуативне, щоб виправдати його в класі з обмеженою кількістю відомих заклинань.",
    "block-section-spells-5-1/item/8": "<<Mass Cure Wounds>> ^^(^^[[1|PHB]]^^)^^: воно вам не повинно знадобитися. Лікує замало, щоб виправдати слот заклинання, тож найкращий випадок його застосування — коли в кількох союзників 0 ХП. Якщо ви дійшли до цього, усе пішло дуже серйозно не так. <<Healing Word>> набагато ефективніше повертає людей до тями, а зважаючи, як мало лікування ви отримуєте від <<Mass Cure Wounds|Масового лікування ран>>, ваші союзники, імовірно, все одно знову впадуть, щойно щось на них косо гляне.",
    "block-section-spells-5-1/item/9": "<<Mislead>> ^^(^^[[1|PHB]]^^)^^: ситуативне. Не чудовий варіант у бою, але поза боєм це пристойно безпечний спосіб розвідати область чи обдурити інших істот.",
    "block-section-spells-5-1/item/10": "<<Modify Memory>> ^^(^^[[1|PHB]]^^)^^: справжній задум заклинання дуже ситуативний, але це заклинання випадково є дуже ефективним «пройди ряткидок або страждай»{{save-or-suck}}. Порівняйте його з <<Hold Monster|Стримуванням монстра>> проти однієї цілі, адже це той самий рівень. <<Hold Monster>> дозволяє додаткові ряткидки щораунду, хоча, звісно, Паралізований небезпечніший за Недієздатний. Ціль не усвідомлює свого оточення, тож ви можете резонно отримати Перевагу на кубику на кидки атаки проти неї, а якщо ціль не зазнає шкоди, ви також можете повністю скувати її до закінчення тривалості заклинання. Проте ціль має Перевагу на кубику на свій ряткидок, якщо ви з нею бʼєтеся, тож вразити її цим треба до початку бою. Зазвичай це означає до кидка ініціативи, але ваш Майстер може дозволити це, якщо істота {{застигнута зненацька|Surprised}}. Якщо вам треба вивести істоту з бою в сутичці з кількома ворогами, ваші вороги, імовірно, не знатимуть, як розірвати ефект (крім як убивши вас), а щойно ви здолаєте решту, можна використати <<Modify Memory|Зміну спогадів>>, щоб переконати ціль, що інші істоти напали на неї, а ви прийшли їй на допомогу. Тоді ви виграли бій і здобули справжній скарб: друзів, яких ви знайшли дорогою, і все, що було в кишенях їхніх колишніх друзів.",
    "block-section-spells-5-1/item/11": "<<Planar Binding>> ^^(^^[[1|PHB]]^^)^^: вкрай ситуативне й дуже дороге. Якщо вивчите його, зачекайте до високого рівня, коли зможете легко дозволити собі матеріальний компонент за 1000 зм і накласти заклинання достатньо високого рівня, щоб викликати щось надзвичайно потужне. Докладніше дивіться наш [[2|практичний гайд із заклинань виклику]].",
    "block-section-spells-5-1/item/12": "<<Raise Dead>> ^^(^^[[1|PHB]]^^)^^: дивно бачити це у списку заклинань Барда. Смерть — частина гри, тож рано чи пізно воно вам знадобиться, але нецікаво витрачати одне зі своїх обмежених відомих заклинань на заклинання, яке ви, можливо, накладете раз чи двічі за весь час.",
    "block-section-spells-5-1/item/13": "<<Rary's Telepathic Bond>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): якщо маєте час його накласти, він має діяти завжди, поки ви перебуваєте в небезпечному місці. Розмова вголос — чудовий спосіб сповістити ворогів про вашу присутність і видати хитрі плани. Те, що після початку дії ефекту обмеження дальності немає, означає, що ним можна спілкуватися із союзниками, поки вони розвідують, потенційно зокрема зі звірами, фамільярами та викликаними істотами.",
    "block-section-spells-5-1/item/14": "<<Scrying>> ^^(^^[[1|PHB]]^^)^^: технічно ситуативне, але це ситуація, що трапляється часто. Щоразу, коли хочете знати, чим займається {{головний лиходій|BBEG}}, накладайте <<Scrying>> і дивіться. Заклинання стає легшим, чим більше ви знаєте ціль, і після однієї зустрічі віч-на-віч можна легко поцупити річ, що повʼязує вас із ціллю, щоб штрафувати її ряткидок.",
    "block-section-spells-5-1/item/15": "<<Seeming>> ^^(^^[[1|PHB]]^^)^^: дуже ситуативне. У більшості кампаній воно не буде достатньо корисним, щоб ви присвятили йому одне зі своїх обмежених відомих заклинань.",
    "block-section-spells-5-1/item/16": "<<Skill Empowerment>> ^^(^^[[1|XGtE]]^^)^^: <<m:Expertise>> для всіх! Ви не накладатимете це на Воїна, щоб той штовхав чи захоплював усе, що зустріне (у вас є кращі бойові бафи), але можна накласти його на персонажа перед скраданням, перед важливою соціальною ситуацією, перед розслідуванням чогось важливого чи майже в будь-який інший час, коли треба зробити важливу перевірку навички й у вас є час заздалегідь підсилити себе.",
    "block-section-spells-5-1/item/17": "<<Synaptic Static>> ^^(^^[[1|XGtE]]^^)^^: почніть із <<Fireball|Вогнекулі>>. Відніміть 30 футів дальності, змініть тип шкоди на психічну й змініть ряткидок на Інтелект. Дуже мало істот добре роблять ряткидки Інтелекту, тож очікуйте, що більшість істот його провалять. 8к6 шкоди здається не вражаючим на цьому рівні заклинання, але віднімання к6 від кидків атаки й перевірок характеристик на цілу хвилину — значний дебаф. Це добрий варіант, щоб почати бій із великою кількістю ворогів-бійців, бо вони постраждають від дебафа найбільше, а більшість ворогів-бійців мають погані ряткидки Інтелекту.",
    "block-section-spells-5-1/item/18": "<<Teleportation Circle>> ^^(^^[[1|PHB]]^^)^^: ситуативне, але загалом одна з найбезпечніших опцій телепортації на великі відстані, особливо тому, що не має обмеження на кількість чи розмір уражених істот. Проте її корисність залежить від наявності зручних кіл телепортації у вашій кампанії. Якщо ваш Майстер не збирається робити такі кола телепортації доступними й корисними, шукайте деінде.",
    "block-section-spells-6-1/item/0": "<<Eyebite>> ^^(^^[[1|PHB]]^^)^^: фантастичне використання слота заклинання: витратьте один слот, і щораунду протягом хвилини ви обираєте істоту та присипляєте її.",
    "block-section-spells-6-1/item/1": "<<Find the Path>> ^^(^^[[1|PHB]]^^)^^: ситуативне й часто складне у використанні, але все одно дуже цікаве. Найважчий момент у застосуванні заклинання — знайти предмет із місця, куди ви хочете потрапити. Щойно ви розвʼязали цю проблему, <<Find the Path>> лише дає вам напрямок. Воно не обходить небезпеки й не вказує на пастки, тож стережіться пасток і засідок дорогою.",
    "block-section-spells-6-1/item/2": "<<Guards and Wards>> ^^(^^[[1|PHB]]^^)^^: надто ситуативне, щоб виправдати його в класі з обмеженою кількістю відомих заклинань.",
    "block-section-spells-6-1/item/3": "<<Heroes' Feast>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): абсолютно чудове заклинання, але з вартістю накладання 1000 зм його не варто вивчати назавжди.",
    "block-section-spells-6-1/item/4": "<<Mass Suggestion>> ^^(^^[[1|PHB]]^^)^^: накажіть потенційній сутичці піти на приємну прогулянку кудись далеко.",
    "block-section-spells-6-1/item/5": "<<Otto's Irresistible Dance>> ^^(^^[[1|PHB]]^^)^^: головна принада цього заклинання в тому, що ціль зазнає ефектів негайно й не може зробити ряткидок, доки не витратить Дію на цей ряткидок, а оскільки вона мусить витратити весь свій рух на танець, то фактично втрачає щонайменше один хід після того, як її обрали ціллю (бонусна дія в неї лишається). Це чудовий спосіб прослизнути повз «Легендарний опір»{{Legendary Resistance}}, а якщо ви добре розташовані в порядку ініціативи, ваші союзники можуть витратити свої ходи, атакуючи ціль із Перевагою на кубику. У багатьох ситуаціях <<Hold Monster|Стримування монстра>> буде не менш ефективним, а то й ефективнішим. <<Hold Monster>> може націлюватися на кількох ворогів і не зважає на імунітет цілі до стану Причарований. Залиште <<Otto's Irresistible Dance>> для потужних одиночних ворогів, яких інакше важко вразити заклинаннями «пройди ряткидок або страждай»{{save-or-suck}}.",
    "block-section-spells-6-1/item/6": "<<Programmed Illusion>> ^^(^^[[1|PHB]]^^)^^: ситуативне, але справді легко зловживане. Воно постійне й саме скидається, тож можна робити всілякі кумедні речі, щоб дурити інших істот. Матеріальний компонент за 25 зм на цьому рівні — дрібниця, тож можна розкидати програмовані ілюзії де завгодно за копійки. Наскільки я можу судити, заклинання можна накладати з областями, що перекриваються, тож можна накласти його тричі, щоб ілюзії запускали одна одну і працювала безперервна ілюзія. На жаль, формулювання заклинання обмежує те, що можна зображати, до «предмета, істоти чи іншого видимого явища», тож кімнату з ілюзорними вартовими, імовірно, створити не вийде. Але все одно можна мати постійного ілюзорного барда, що грає 15-хвилинну петлю пісень.",
    "block-section-spells-6-1/item/7": "<<True Seeing>> ^^(^^[[1|PHB]]^^)^^: ситуативне, але там, де воно застосовне, його здебільшого не здолати.",
    "block-section-spells-7-1/item/0": "<<Dream of the Blue Veil>> ^^(^^[[1|TCoE]]^^)^^ (необовʼязкове): це більше сюжетний прийом, ніж заклинання. Не вивчайте його, якщо вам не скаже Майстер.",
    "block-section-spells-7-1/item/1": "<<Etherealness>> ^^(^^[[1|PHB]]^^)^^: надзвичайно ефективний варіант розвідки чи втечі. Якщо ви не бʼєтеся з етерними ворогами, ви недоторканні. Ви бачите й чуєте Матеріальний план (хоч і на обмеженій відстані), що дозволяє шпигувати за іншими істотами особисто без їхнього відома. Заклинання триває 8 годин, чого достатньо, щоб зробити багато чого, потенційно навіть Довгий відпочинок.",
    "block-section-spells-7-1/item/2": "<<Forcecage>> ^^(^^[[1|PHB]]^^)^^: абсолютно чудовий спосіб ізолювати або свою групу, або ворогів. Тривалість достатня, щоб відпочити Коротким відпочинком, а ворогам не дозволено ряткидка, щоб опиратися. Нехай союзник накладе заклинання зі шкодою по області, що діє з часом, як-от <<Hunger of Hadar>>, а потім накладіть зверху <<Forcecage|Силову кліть>>, і ви граєте в магічну гру «Чи перемелеться?».",
    "block-section-spells-7-1/item/3": "<<Mirage Arcane>> ^^(^^[[1|PHB]]^^)^^: це складне заклинання. Область дії величезна, дальність — Поле зору (піднімітеся на гору в ясний день), а ефекти ілюзії настільки відчутні, що з ними можна фізично взаємодіяти, зокрема підбирати палиці чи камені. Але незрозуміло, як далеко це заходить: чи можна спалити ілюзорні дрова, щоб зігрітися? Чи можна згладити складну місцевість так само, як гладку місцевість можна зробити складною? Чи можна влаштувати сходи в стіні прямовисної скелі? Наскільки вгору й униз сягає ефект? Найближче, що в нас є, — ці [[2|два]] [[3|твіти]], які вказують, що у вас є великий простір для маневру, а ефекти достатньо реальні, щоб істота могла втопитися в ілюзорній воді, згоріти в ілюзорній лаві й лазити ілюзорними деревами. Те, що вам зійде з рук, остаточно вирішуватиме ваш Майстер, але саме заклинання — шалено універсальний набір інструментів.",
    "block-section-spells-7-1/item/4": "<<Mordenkainen's Magnificent Mansion>> ^^(^^[[1|PHB]]^^)^^: у реальному світі вміння накладати це заклинання означало б, що можна спокійно йти на пенсію. Щодня ви виходили б із особняка, знову накладали заклинання, щоб відтворити будинок на 24 години, а потім поверталися б у своє невидиме позапланове житло, щоб насолодитися ще 24 годинами достатку їжі, комфорту й майже невидимих слуг. Розмір особняка становить 5000 квадратних футів — цілком достатньо, щоб розмістити групу авантюристів і чималу свиту. Запропоновані 100 гостей бенкету мали б по 50 квадратних футів (область 5×10) простору для себе, але вправно спланований особняк легко перетворив би цей простір на велику спільну залу для бенкетів і набір невеликих кімнат із двоярусними ліжками, щоб відсипатися після чарівного обіду з 9 страв. Проте в суто механічному плані це заклинання, яке Бард не може собі дозволити вивчити. Є багато менш витратних способів розвʼязати ті самі проблеми, а кількість заклинань, які ви можете вивчити, строго обмежена.",
    "block-section-spells-7-1/item/5": "<<Mordenkainen's Sword>> ^^(^^[[1|PHB]]^^)^^: це обʼєктивно погане заклинання. Порівняйте його з <<Bigby's Hand|Дланню Бігбі>>, і все цілком зрозуміло. <<Bigby's Hand|Длані Бігбі>> у списку заклинань Барда, на жаль, немає, але саме для цього існують <<q:Magical Secrets>>.",
    "block-section-spells-7-1/item/6": "<<Prismatic Spray>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): непередбачувано. Область дії чудова, а ефекти 6, 7 і 8 — усі чудові (будь-які два промені були б вражаючими), але заклинання непередбачуване, а я завжди неохоче рекомендую непередбачувані заклинання, бо непередбачуване часто означає ненадійне.",
    "block-section-spells-7-1/item/7": "<<Project Image>> ^^(^^[[1|PHB]]^^)^^: <<Mislead>> з довшою тривалістю й кращою дальністю. Формулювання, що описують можливості копії, майже ідентичні. Додаткова дальність додає трохи універсальності, але заклинання все одно доволі ситуативне.",
    "block-section-spells-7-1/item/8": "<<Regenerate>> ^^(^^[[1|PHB]]^^)^^: надто ситуативне, щоб обирати його заклиначу з обмеженою кількістю відомих заклинань. У D&D немає правил травм, що ведуть до втрати кінцівок, хіба що за дуже специфічних обставин, тож персонажі не втрачають пальці рук і ніг, хоча потенційно роками їх рубають і шматують усілякі супротивники.",
    "block-section-spells-7-1/item/9": "<<Resurrection>> ^^(^^[[1|PHB]]^^)^^: якщо ви вивчили <<Raise Dead>>, можете замінити його на <<Resurrection>>, але я не думаю, що <<Resurrection>> — значне покращення порівняно з <<Raise Dead|Оживленням мерців>>.",
    "block-section-spells-7-1/item/10": "<<Symbol>> ^^(^^[[1|PHB]]^^)^^: хоч багато ефектів чудові, неможливість перемістити символ і висока вартість накладання роблять його неприйнятним.",
    "block-section-spells-7-1/item/11": "<<Teleport>> ^^(^^[[1|PHB]]^^)^^: з дальністю 10 футів і до 8 цілей ви легко телепортуєте всю свою групу, а без потреби триматися за руки в колі часто можна врятувати всю групу посеред бою без особливих труднощів. Проте в <<Teleport|Телепорті>> складна механіка, повʼязана з тим, наскільки добре ви знаєте місце призначення, і часто є ймовірність невдачі. Обовʼязково прихоплюйте сувенір із нових місць, щоб за потреби легко повернутися без ризику невдачі.",
    "block-section-spells-8-1/item/0": "<<Antipathy/Sympathy>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): складно використовувати, бо воно націлюється на один тип істот, але якщо ви стикаєтеся з однорідною групою ворогів, можна сильно їх ускладнити будь-яким із варіантів. Навіть проти окремих істот використання варіанта «Симпатія», щоб змусити ворога підійти до когось із вашої групи («Симпатія» на паладині, щоб приманити ліча), може заманити ворогів у ситуацію, яка закінчиться їхньою смертю. Утім, це ситуативне заклинання, яке корисним бути не обовʼязково, тож його важко рекомендувати класу, що вивчає свої заклинання назавжди.",
    "block-section-spells-8-1/item/1": "<<Dominate Monster>> ^^(^^[[1|PHB]]^^)^^: імовірно, найкраще заклинання типу «пройди ряткидок або страждай»{{save-or-suck}} у грі. З досконалим контролем над істотою на такий довгий час можна зробити багато. Використання цілі як підданого в бою, очевидно, спокушає, але ціль повторює ряткидок щоразу, коли отримує шкоду, тож будьте дуже обережні, якщо вирішите так робити.",
    "block-section-spells-8-1/item/2": "<<Feeblemind>> ^^(^^[[1|PHB]]^^)^^: заклиначі надзвичайно вразливі до <<Feeblemind|Слабоумства>>. Навіть істоти, що накладають заклинання як доповнення до інших здібностей, можуть серйозно постраждати від того, що раптом стають менш розумними за багатьох тварин. Окрім втрати здатності накладати заклинання, мені завжди було важко розібратися з цим заклинанням щодо інших ворогів. 1 Інтелект і 1 Харизма — очевидно, дуже погано, але на що здатна жертва? Чи може персонаж користуватися класовими уміннями, окрім чаротворства? Наскільки вони розумні, щоб щось робити в бою? Майстер має багато простору для тлумачення того, як це працює й які здібності істоти ще можуть використовувати. Хоч це може бути весело й дуже ефективно, це також робить ефект заклинання цілком залежним від Майстра та його тлумачення того, на що вражена істота розумово здатна.",
    "block-section-spells-8-1/item/3": "<<Glibness>> ^^(^^[[1|PHB]]^^)^^: перевірки Харизми охоплюють такі навички, як Переконання, а ще й перевірки характеристики для <<Counterspell|Контрчарів>> і <<Dispel Magic|Розвіювання магії>>. Накладіть його перед боєм із ворожим заклиначем і насолоджуйтеся тим, як майже без зусиль скасовуєте все, що він накладає.",
    "block-section-spells-8-1/item/4": "<<Mind Blank>> ^^(^^[[1|PHB]]^^)^^: ситуативно, але кумедно, якщо у вашій групі є Варвар-берсерк.",
    "block-section-spells-8-1/item/5": "<<Power Word Stun>> ^^(^^[[1|PHB]]^^)^^: ризикувати, граючи на поточних ХП істоти, важко, особливо тому, що на цьому рівні у вас так мало слотів заклинань, але якщо ви зможете підгадати це по пораненому ворогу (або ворогу з низьким максимумом ХП, як у багатьох заклиначів), воно може вивести його з сутички достатньо надовго, щоб ви перемогли здебільшого без опору.",
    "block-section-spells-9-1/item/0": "<<Foresight>> ^^(^^[[1|PHB]]^^)^^: це, безперечно, найкращий баф у грі. З тривалістю 8 годин ви можете накласти його на щасливого отримувача й дивитися, як він сміється, проходячи майже будь-яке випробування протягом цілого дня пригод.",
    "block-section-spells-9-1/item/1": "<<Mass Polymorph>> ^^(^^[[1|XGtE]]^^)^^: ви жертвуєте абсолютною силою <<True Polymorph|Істинного перевтілення>> заради можливості вплинути щонайбільше на 10 істот. Правила щодо істот без ПН (вашої групи) написано так, що це стає справді непривабливим порівняно з <<True Polymorph|Істинним перевтіленням>>. Порівняно з перетворенням одного союзника на дракона з ПН 17+, перетворення до 10 ваших союзників на тиранозаврів (тиранозаврусів? тиранозаври?) просто не таке ефективне, навіть якщо фраза «Я перетворюю нас і наших коней на тиранозаврів» — одна з найкрутіших речей, які я можу придумати сказати під час гри. На жаль, цілі набувають розумових характеристик звіра, тож перетворення вашої групи авантюристів на зубастих ящірок може насправді зробити їх слабшими. Заклинання можна використати наступально, а цілі не роблять ряткидків, окрім першого, тож перетворіть своїх ворогів на слимаків чи щось подібне й закиньте їх на Стихійний план Вогню чи в інше не менш неприємне місце.",
    "block-section-spells-9-1/item/2": "<<Power Word Heal>> ^^(^^[[1|PHB]]^^)^^: повне зцілення й зняття купи станів одним заклинанням дуже спокушає, але запобігання всій цій шкоді та всім цим станам за допомогою <<Foresight|Передбачення>> працюватиме набагато краще.",
    "block-section-spells-9-1/item/3": "<<Power Word Kill>> ^^(^^[[1|PHB]]^^)^^: 100 ХП — дуже низька межа, але важко заперечити, наскільки ефективно просто вбити істоту без жодних кидків. Наприклад, у чарівника 20-го рівня зі Статурою 12 буде 102 ХП (6+19\\*4+20), тож практично ніхто з тих, хто лякає на цьому рівні, не буде вразливим одразу, але якщо ваші союзники здатні швидко завдати купу шкоди, ви можете використати це вже в 1-му раунді бою.",
    "block-section-spells-9-1/item/4": "<<Prismatic Wall>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): найкраще заклинання контролю області. Тривалість 10 хвилин, ви й ваші союзники можете проходити крізь неї неушкодженими, а якщо вороги проходять крізь неї, вони можуть отримати до 50к6 шкоди, бути обернені на камінь і відправлені на інший план. Стіну можна зруйнувати, але процес для цього такий кумедно набридливий, що я сумніваюся, чи хтось справді спробує (це реліквія ранніх редакцій D&D).",
    "block-section-spells-9-1/item/5": "<<Psychic Scream>> ^^(^^[[1|XGtE]]^^)^^: до 10 істот у межах 90 футів від вас у будь-якому напрямку. Ряткидки Інтелекту в середньому найслабші, навіть для монстрів із високим ПН, тож у багатьох випадках можна Приголомшити ворогів і тримати їх приголомшеними неймовірно довго. Ефект приголомшення не має тривалості, тож вороги зі слабким Інтелектом можуть бути *приголомшені назавжди*. Шкода пристойна, але це абсолютно другорядна річ порівняно з ефектом приголомшення.",
    "block-section-spells-9-1/item/6": "<<True Polymorph>> ^^(^^[[1|PHB]]^^)^^: потужне й універсальне, а ще триває цілу годину. Це заклинання, що справді винагороджує ґрунтовне знання монстрів 5e, тож сядьте з «Бестіарієм»{{Monster Manual}} тощо й трохи почитайте. Вам знадобиться основна бойова форма з ПН 17, 18, 19 і 20 на випадок, коли треба перетворити себе чи союзника на монстра, але також варто знайти хорошу форму з ПН 9, якщо треба перевтілити предмет на улюбленця. Памʼятайте, що заклинання стає постійним, якщо підтримувати його годину, тож ним також можна назавжди перетворити себе чи когось іншого на монстра, чи дракона, чи щось таке. Ви втратите все своє класове добро, бо набуваєте характеристик істоти, але чесно кажучи, дракон із ПН 20 усе одно набагато потужніший. Остання опція заклинання дозволяє перетворити істоту на предмет (що дозволяє ряткидок Мудрості). Перетворіть її на квітковий горщик, а потім або скиньте з достатньої висоти, щоб завдати максимальної шкоди від падіння (додаткова шкода переходить на її звичайні ХП, коли вона повертається), або закиньте в напівплан, або відправте <<Plane Shift|Планарним переходом>> у якесь неприємне місце, або позбудьтеся її якимось іншим постійним і незворотним способом, як-от <<q:Bag of Devouring|Мішком пожирання>>. Більше читайте в нашому [[2|практичному гайді про «<<c:True Polymorph>>» і «<<c:Shapechange>>»]].",
}

FRAGMENTS = {key: refs.pair_label_marker(value) for key, value in refs.expand_all(FRAGMENTS).items()}
